/* ===== Writer F: romance lines — wade, ashley, ines, roz, kyle, delphine, grace, maya ===== */
(()=>{
const TRUTH=id=>()=>rel(id).truth===true||NEED(t('真话时刻之后','After the moment of truth','Depois do momento da verdade'));
const DMETA=id=>NM(id)+' · '+t('约会','Date','Encontro');
const CMETA=id=>NM(id)+' · '+t('关系危机','Rough patch','Crise');

Object.assign(ROMX,{
 wade:{beats:[
  t('他教你甩套索。你套中了一根栅栏桩，他说：“桩子也算。”','He teaches you to throw a rope. You catch a fence post. "Post counts," he says.','Ensina-te a laçar. Apanhas um poste da cerca. «O poste também conta», diz ele.'),
  t('收工后他坐在皮卡后斗上，看你在烟盒背面画那座老谷仓。他看了很久，什么也没说，把烟盒收进了衬衫口袋。','After work he sits on the tailgate watching you sketch the old barn on the back of a cigarette pack. He looks a long while, says nothing, and tucks the pack into his shirt pocket.','Depois do trabalho senta-se na caixa da carrinha a ver-te desenhar o celeiro velho nas costas de um maço de tabaco. Olha muito tempo, não diz nada e guarda o maço no bolso da camisa.'),
  t('他说他父亲也送他去念过书，农学院，一个学期。“有些东西不是不想要，是要不起。”这是你听他说过最长的一句话。','He says his father sent him to school once too — ag college, one semester. "Some things you don\'t quit wanting. You just can\'t afford \'em." Longest sentence you\'ve ever heard from him.','Diz que o pai também o mandou estudar — escola agrícola, um semestre. «Há coisas que não se deixa de querer. Só não se pode pagá-las.» A frase mais comprida que alguma vez lhe ouviste.'),
  t('他把那个烟盒钉在了工具房的门背后，旁边是他母亲的照片，和一条 1987 年牛仔竞技赛的奖带。','He\'s nailed the cigarette pack to the back of the tool-shed door, next to a photo of his mother and a 1987 rodeo ribbon.','Pregou o maço de tabaco nas costas da porta do barracão das ferramentas, ao lado de uma fotografia da mãe e de uma fita de um rodeo de 1987.')],
  epilogue:t('雷耶斯牧场北边立起了一座新谷仓，图纸是你画的，钉子是他敲的。韦德还是不怎么说话，但每天傍晚，他都把皮卡停在店门口，按一下喇叭，等你。','A new barn stands on the north end of the Reyes Ranch. You drew it; he nailed it. Wade still doesn\'t say much, but every evening he pulls his truck up outside the shop, taps the horn once, and waits for you.','Há um celeiro novo no extremo norte do Rancho Reyes. Tu desenhaste-o; ele pregou-o. O Wade continua a falar pouco, mas todos os fins de tarde para a carrinha à porta do restaurante, toca uma vez a buzina e espera por ti.')},
 ashley:{beats:[
  t('她让你在体育场看台上跑上跑下二十趟。第十四趟你吐了，她递给你一瓶水：“好。现在我知道你的底在哪儿了。”','She has you run the stadium bleachers twenty times. On the fourteenth you throw up. She hands you water. "Good. Now I know where your floor is."','Põe-te a subir e descer as bancadas do estádio vinte vezes. À décima quarta vomitas. Ela dá-te água. «Ótimo. Agora sei onde está o teu limite.»'),
  t('她说她当过大学田径队员，膝盖废了以后，有一年没照过镜子。她说得很平静，像在念训练记录。','She says she ran track in college. After her knee went, she didn\'t look in a mirror for a year. She says it flatly, like reading from a training log.','Conta que fazia atletismo na universidade. Depois de o joelho se ir, passou um ano sem se ver ao espelho. Di-lo sem emoção, como quem lê um registo de treino.'),
  t('她在你的训练计划上加了一栏，叫“为什么”。第一周你写的是“为了好看”。她划掉了，说再想想。','She adds a column to your training plan called "Why." The first week you write "to look good." She crosses it out and tells you to think again.','Acrescenta uma coluna ao teu plano de treino chamada «Porquê». Na primeira semana escreves «para ficar bonito». Ela risca e diz-te para pensares outra vez.'),
  t('校队输了球，她一个人坐在空看台上。你坐过去，她把头靠在你肩上：“别动。这一下不算训练。”','The team loses and she sits alone in the empty bleachers. You sit down beside her and she leans her head on your shoulder. "Don\'t move. This doesn\'t count as training."','A equipa perde e ela fica sozinha na bancada vazia. Sentas-te ao lado dela e ela encosta a cabeça ao teu ombro. «Não te mexas. Isto não conta como treino.»')],
  epilogue:t('你训练计划上“为什么”那一栏，最后写的是她的名字。她划掉了，说太肉麻，又趁你不注意写了回去。每个周五晚上，你坐在教练席正后方，替她数暂停次数。','In the "Why" column of your training plan, the last thing you wrote was her name. She crossed it out — too corny — then wrote it back in when you weren\'t looking. Every Friday night you sit right behind the bench and count her timeouts for her.','Na coluna «Porquê» do teu plano de treino, a última coisa que escreveste foi o nome dela. Ela riscou — piroso demais — e voltou a escrevê-lo quando não estavas a ver. Todas as sextas à noite sentas-te mesmo atrás do banco e contas-lhe os descontos de tempo.')},
 ines:{beats:[
  t('她把回程机票改签了一次。“别多想，改签便宜。”她不看你的眼睛。','She changes her return flight. "Don\'t read into it. Changing was cheap." She doesn\'t look you in the eye.','Muda o voo de regresso. «Não penses nisso. Ficou barato mudar.» Não te olha nos olhos.'),
  t('她在店里帮你包了一下午鳕鱼饼，手法跟你妈一模一样。是你妈教的，在你走了以后。','She spends an afternoon in the shop shaping salt cod fritters with you, exactly the way your mother does. Your mother taught her — after you left.','Passa uma tarde no restaurante a fazer pastéis de bacalhau contigo, exatamente como a tua mãe faz. Foi a tua mãe que a ensinou — depois de te ires embora.'),
  t('她说你走的那天，她去了机场，在安检口外面站了两个小时。想好的话，一句也没说出口。','She says the day you left, she went to the airport and stood outside security for two hours. Every word she\'d planned stayed in her mouth.','Diz que no dia em que partiste foi ao aeroporto e ficou duas horas à porta do controlo de segurança. Tudo o que tinha preparado ficou por dizer.'),
  t('她站在店后那块空地上：“这里倒有点像阿尔法马的天台，只是没有河。”过了一会儿又说：“也没有你妈妈。”','She stands on the empty lot behind the shop. "It\'s a bit like the rooftops in Alfama. Only there\'s no river." A while later: "And no mother of yours."','Fica no terreno vazio atrás do restaurante. «Isto parece um bocadinho os terraços de Alfama. Só que não há rio.» Pouco depois: «Nem a tua mãe.»')],
  epilogue:t('伊内丝每个月从里斯本寄来一个包裹：羽衣甘蓝种子、旧报纸、你妈妈手写的菜谱。一周年那天的包裹里只有一张字条：“下次你来。机票我已经买好了。”','Every month Inês sends a parcel from Lisbon: kale seeds, old newspapers, recipes in your mother\'s handwriting. On the anniversary the parcel holds a single note: "Next time, you come. I\'ve already bought the ticket."','Todos os meses a Inês manda uma encomenda de Lisboa: sementes de couve, jornais velhos, receitas com a letra da tua mãe. No dia do aniversário a encomenda traz só um bilhete: «Da próxima vens tu. O bilhete já está comprado.»')},
 roz:{beats:[
  t('她在餐巾纸上给你画地下的岩层，一层一层，像千层酥。“石油不是地下的湖，是海绵里的水。”','She draws the rock layers underground on a napkin, layer on layer like puff pastry. "Oil isn\'t a lake down there. It\'s water in a sponge."','Desenha num guardanapo as camadas de rocha lá em baixo, camada sobre camada, como massa folhada. «O petróleo não é um lago. É água dentro de uma esponja.»'),
  t('她说她是休斯敦一个焊工的女儿，家里第一个上大学的人。“我爸说，别给比你笨的人干活。我一直在违背他。”','She\'s a Houston welder\'s daughter, first in her family to go to college. "Daddy said never work for anybody dumber than you. I\'ve been disobeying him for years."','É filha de um soldador de Houston, a primeira da família a ir para a universidade. «O meu pai dizia para nunca trabalhar para alguém mais burro do que eu. Ando há anos a desobedecer-lhe.»'),
  t('你告诉她的事，她用工程师的方式消化：第二天，她带来一张手画的地块图。罐头厂、你的空地、新匝道，三条线交在你店后面。','She digests what you told her like an engineer: next day she brings a hand-drawn site map. The cannery, your lot, the new ramp — three lines meeting behind your shop.','Digere o que lhe contaste como uma engenheira: no dia seguinte traz uma planta desenhada à mão. A fábrica, o teu terreno, o novo acesso — três linhas que se cruzam atrás do restaurante.'),
  t('她开始把特拉维斯的邮件存进一个私人硬盘。“不是为了你，是为了我晚上睡得着。”过了一会儿：“也有一点是为了你。”','She\'s started copying Travis\'s emails onto a private hard drive. "Not for you. So I can sleep at night." A beat later: "Little bit for you."','Começou a copiar os emails do Travis para um disco pessoal. «Não é por ti. É para conseguir dormir.» Um instante depois: «Um bocadinho por ti.»')],
  epilogue:t('罗兹辞了油田的工作，去奥斯汀一家做地下水治理的公司上班，每个周五晚上开一个小时车回来。她说圣鲁伊斯地下的每一层岩石，她都替你记着。','Roz quit the oilfield and took a job with a groundwater cleanup outfit in Austin. Every Friday night she drives the hour back. She says she keeps track of every rock layer under San Luís, for you.','A Roz deixou o petróleo e foi trabalhar para uma empresa de descontaminação de águas subterrâneas em Austin. Todas as sextas à noite faz a hora de caminho de volta. Diz que guarda de cor cada camada de rocha debaixo de San Luís, por ti.')},
 kyle:{beats:[
  t('他把你教的法多指法用进了一首乡村歌，效果奇怪地好听。厄尔说这是他听过最伤心的两步舞曲。','He works your fado fingering into a country song and it sounds strangely good. Earl calls it the saddest two-step he\'s ever heard.','Mete o dedilhado de fado que lhe ensinaste numa canção country e soa estranhamente bem. O Earl diz que é o two-step mais triste que alguma vez ouviu.'),
  t('他修拖拉机的时候也哼歌，手上全是机油，在你的乐谱上留下一个黑指纹。他说那是签名。','He hums while he fixes tractors, hands black with grease, and leaves a thumbprint on your sheet music. He says that\'s his autograph.','Cantarola enquanto arranja tratores, mãos pretas de óleo, e deixa uma impressão digital na tua partitura. Diz que é o autógrafo dele.'),
  t('唱完整首法多的那晚之后，他开始叫你“搭档”。不是乐队的那种。他说的时候，耳朵红了。','After the night you sang the whole fado, he starts calling you "partner." Not the band kind. His ears go red when he says it.','Depois da noite em que cantaram o fado inteiro, começa a chamar-te «parceiro». Não no sentido da banda. As orelhas ficam-lhe vermelhas quando o diz.'),
  t('他说他十七岁就知道自己喜欢男人，在这个镇上一直把这件事锁在工具箱最底下。“和你唱歌的时候，那个箱子是开着的。”','He says he\'s known he likes men since he was seventeen, and in this town he\'s kept it locked at the bottom of his toolbox. "When I sing with you, that box is open."','Diz que sabe que gosta de homens desde os dezassete anos e que, nesta terra, sempre guardou isso no fundo da caixa de ferramentas. «Quando canto contigo, essa caixa está aberta.»')],
  epilogue:t('孤星法多录了第一张唱片，十首歌，在奥斯汀的唱片店卖掉了四十七张。封面是你们俩坐在店门口台阶上的照片，凯尔手上还沾着机油。','Lone Star Fado cut its first record — ten songs, forty-seven copies sold at a record store in Austin. The cover is the two of you on the shop steps, grease still on Kyle\'s hands.','Os Lone Star Fado gravaram o primeiro disco — dez canções, quarenta e sete exemplares vendidos numa loja de discos em Austin. A capa é uma fotografia dos dois nos degraus do restaurante, com óleo ainda nas mãos do Kyle.')},
 delphine:{beats:[
  t('她点菜从来不看菜单，看你。“今天你想让我吃什么？我要的是你的判断，不是菜单。”','She never looks at the menu when she orders. She looks at you. "What do you want me to eat today? I want your judgment, not the menu\'s."','Nunca olha para a ementa quando pede. Olha para ti. «O que queres que eu coma hoje? Quero o teu critério, não o da ementa.»'),
  t('她给你看博客后台：粉丝数、点击率、哪道菜的照片转发最多。她看数字的眼神，跟你看炭火一模一样。','She shows you her blog dashboard: followers, click-through, which dish got shared most. She watches those numbers the way you watch coals.','Mostra-te o painel do blogue: seguidores, cliques, que prato foi mais partilhado. Olha para aqueles números como tu olhas para as brasas.'),
  t('真话之后，她不再催你改名。她拍了一张招牌的特写，若泽当年手写的那几个字，配文只有一句：“有些名字不需要好念。”','After that honest talk she stops pushing the rename. She posts a close-up of the sign, José\'s old hand-painted letters, captioned only: "Some names don\'t need to be easy."','Depois daquela conversa franca, deixa de insistir no nome. Publica um grande plano da tabuleta, as letras pintadas à mão pelo José, com uma só legenda: «Há nomes que não precisam de ser fáceis.»'),
  t('她承认她在奥斯汀其实很孤独。三百个朋友，没有一个会在她生病的时候送汤。“你这儿的老太太给我送过。我都没告诉她我病了。”','She admits she\'s lonely in Austin. Three hundred friends, not one who\'d bring her soup when she\'s sick. "Your old lady here brought me some. I never even told her I was sick."','Confessa que em Austin é sozinha. Trezentos amigos e nenhum lhe levaria sopa quando está doente. «A tua senhora de cá levou-me. Eu nem lhe tinha dito que estava doente.»')],
  epilogue:t('店名一个字都没改。德尔菲娜把博客改名叫《孤星下的里斯本》，一半写奥斯汀，一半写你的厨房。她终于学会了在打分之前先问一句：“这道菜想说什么？”','The name on the sign didn\'t change by a letter. Delphine renamed her blog "Lisbon Under the Lone Star" — half Austin, half your kitchen. She\'s finally learned to ask, before she scores anything: "What is this dish trying to say?"','O nome da tabuleta não mudou uma letra. A Delphine mudou o nome do blogue para «Lisboa sob a Estrela Solitária» — metade Austin, metade a tua cozinha. Aprendeu finalmente a perguntar, antes de dar nota: «O que é que este prato quer dizer?»')},
 grace:{beats:[
  t('她在文件夹里夹了一张便利贴，写着你上周念错的三个法律词和正确的读法。没有署名。','She tucks a sticky note into the folder: three legal words you mispronounced last week, with the right way to say them. Unsigned.','Deixa um post-it dentro da pasta: três termos jurídicos que pronunciaste mal na semana passada, com a pronúncia certa. Sem assinatura.'),
  t('她说她在达拉斯的大律所干过四年。有一天在电梯里，她忘了自己是哪一层的人，第二个月就搬回了圣鲁伊斯。','She says she spent four years at a big Dallas firm. One day in the elevator she forgot which floor she belonged to. A month later she moved back to San Luís.','Conta que passou quatro anos numa grande sociedade de advogados em Dallas. Um dia, no elevador, esqueceu-se de qual era o andar dela. No mês seguinte voltou para San Luís.'),
  t('她不再在办公室见你，改成夜跑。沿着主街跑到教堂再跑回来，一边跑一边谈遗嘱以外的一切。','She stops meeting you at the office. Night runs instead — down Main Street to the church and back, talking about everything except the will.','Deixa de te receber no escritório. Passam a correr à noite — rua principal até à igreja e volta, a falar de tudo menos do testamento.'),
  t('她给你看若泽签遗嘱那天的会议记录。页边有一行她当年的铅笔字：“他哭了。别写进去。”','She shows you her notes from the day José signed the will. In the margin, in her pencil: "He cried. Leave it out."','Mostra-te as notas do dia em que o José assinou o testamento. Na margem, a lápis, com a letra dela: «Chorou. Não pôr isto.»')],
  epilogue:t('一周年那天，你签完最后一份文件，格蕾丝把那支按了一整年的圆珠笔留给了你：“遗嘱办完了。接下来你问我什么，我都不用当律师来回答。”','On the anniversary you sign the last document, and Grace leaves you the ballpoint she\'s been clicking all year. "The will\'s done. Whatever you ask me now, I don\'t have to answer as a lawyer."','No dia do aniversário assinas o último documento e a Grace deixa-te a esferográfica que andou a carregar o ano inteiro. «O testamento está tratado. O que me perguntares agora, já não tenho de responder como advogada.»')},
 maya:{beats:[
  t('她给你看奥斯汀几所大学的招聘网页，每一页都用荧光笔划过。“只是看看。”她划了十七页。','She shows you job listings from Austin universities, every page highlighted. "Just looking." Seventeen pages of just looking.','Mostra-te anúncios de emprego de universidades de Austin, todas as páginas sublinhadas a marcador. «Só estou a ver.» Dezassete páginas só a ver.'),
  t('她父母在休斯敦开了二十五年洗衣店。“他们说我读到博士，就不用再闻漂白水了。结果我在这儿闻牛粪。”','Her parents have run a laundromat in Houston for twenty-five years. "They said if I got a doctorate I\'d never smell bleach again. Now I smell cows."','Os pais dela têm uma lavandaria em Houston há vinte e cinco anos. «Diziam que, se eu fizesse o doutoramento, nunca mais cheirava a lixívia. Agora cheiro a vacas.»'),
  t('说了实话以后，她不再每周五劝你去奥斯汀。她开始问：“如果留下，你会想要什么？”她问的时候，好像也在问自己。','After the truth, she stops pitching Austin every Friday. Instead she asks: "If you stayed, what would you want?" She sounds like she\'s asking herself too.','Depois da verdade, deixa de te falar de Austin todas as sextas. Em vez disso pergunta: «Se ficasses, o que é que quererias?» Parece que se pergunta a si própria também.'),
  t('她在你店里改作业改到打烊，红笔批注越写越短。最后一份上只写了一句：“写得好。别走。”她盯着那行字，说是写给学生的。','She grades in your shop until closing, her red comments getting shorter and shorter. The last paper just says: "Good work. Don\'t leave." She stares at it and says it\'s for the student.','Corrige trabalhos no teu restaurante até à hora de fechar, os comentários a vermelho cada vez mais curtos. O último diz só: «Bom trabalho. Não te vás embora.» Fica a olhar e diz que é para o aluno.')],
  epilogue:t('玛雅去了奥斯汀，可每个周五晚上都开一个小时车回圣鲁伊斯，不是来劝你走，是来喝店里的咖啡。她说，这是她第一次在一个地方续租第二年。','Maya went to Austin, but every Friday night she drives the hour back to San Luís — not to talk you into leaving, just for the coffee. She says it\'s the first time she\'s ever renewed a lease for a second year.','A Maya foi para Austin, mas todas as sextas à noite faz a hora de caminho até San Luís — não para te convencer a sair, só pelo café. Diz que é a primeira vez que renova um contrato de arrendamento por um segundo ano.')}
});

STORY.push(
/* ---------- WADE ---------- */
{id:'rF_wade_date',when:()=>S.week>=13&&S.day===6&&S.slot===0&&rel('wade').met&&rel('wade').like>=4&&rel('wade').trust>=3,run:()=>({
 title:t('老谷仓','The old barn','O celeiro velho'),meta:DMETA('wade'),
 text:[t('天刚亮，韦德的皮卡停在店门口，按了一下喇叭，没下车。他把你拉到雷耶斯牧场最北边，一座塌了半边的老谷仓前。','At first light Wade\'s truck pulls up outside the shop. One tap of the horn. He doesn\'t get out. He drives you to the far north end of the Reyes Ranch, to an old barn caved in on one side.','Ao romper do dia a carrinha do Wade para à porta do restaurante. Um toque de buzina. Ele não sai. Leva-te até ao extremo norte do Rancho Reyes, a um celeiro velho meio desabado.'),
  t('“1952 年盖的。老板想拆，我想修。”他递给你一卷皮尺，“你学过这个。”','"Built in \'52. Boss wants it torn down. I want it fixed." He hands you a tape measure. "You studied this."','«Construído em 52. O patrão quer deitá-lo abaixo. Eu quero arranjá-lo.» Estende-te uma fita métrica. «Tu estudaste isto.»')],
 choices:[
  {t:t('量尺寸，画一张正经的修复图','Take measurements and draw a proper restoration plan','Tirar medidas e fazer uma planta de recuperação a sério'),req:()=>S.stats.oficio>=35||NEED(t('手艺 35','Craft 35','Ofício 35')),fx:()=>{addTrust('wade',2);addLike('wade',1);stat('oficio',2);S.flags.rF_wadeBarn=true},
   next:()=>say('',t('你在皮卡引擎盖上画了一上午。他看图的时候，用拇指抹平被风吹起的纸角，像在摸一匹马。','You draw all morning on the hood of the truck. When he looks it over, he smooths the paper\'s corner flat with his thumb, like he\'s gentling a horse.','Desenhas a manhã toda em cima do capô. Quando ele olha para a planta, alisa com o polegar o canto do papel que o vento levanta, como quem acalma um cavalo.'),t('信任 +2 · 手艺 +2','Wade trust +2 · Craft +2','Confiança do Wade +2 · Ofício +2'))},
  {t:t('告诉他你为什么不画了','Tell him why you stopped drawing','Contar-lhe porque deixaste de desenhar'),req:TRUTH('wade'),fx:()=>{addTrust('wade',2);addLike('wade',2);stat('saud',-3)},
   next:()=>say('',t('你说完，他收回皮尺：“那今天不画，只修。”你们换了三根椽子，再没说一句话。这是你来德州以后最轻松的一个早晨。','When you\'re done he takes the tape back. "No drawing today, then. Just fixing." You replace three rafters without another word. It\'s the easiest morning you\'ve had since Texas.','Quando acabas, ele guarda a fita. «Então hoje não se desenha. Só se arranja.» Trocam três vigas sem mais uma palavra. É a manhã mais leve que tiveste desde que chegaste ao Texas.'))},
  {t:`[${faceWord()}] `+t('脱掉上衣，抢着搬木头','Strip off your shirt and haul lumber','Tirar a camisa e carregar as tábuas'),req:()=>S.muscle>=2||NEED(t('肌肉 2 级','Muscle level 2','Músculo nível 2')),fx:()=>{addLike('wade',1);addTrust('wade',-0.5);flirt()},
   next:()=>say('',t('他看了你一眼，把自己的手套扔过来：“木刺。”就这样。你分不清他是没注意，还是注意了。','He glances over and tosses you his gloves. "Splinters." That\'s it. You can\'t tell if he didn\'t notice or did.','Olha de relance e atira-te as luvas dele. «Farpas.» Mais nada. Não percebes se não reparou ou se reparou.'))}]})},
{id:'rF_wade_crisis',when:()=>S.week>20&&S.week>=30&&S.day===3&&S.slot===0&&rel('wade').truth===true&&!!S.flags.ev_rF_wade_date,run:()=>({
 title:t('塌了','Caved in','Desabou'),meta:CMETA('wade'),
 text:[t('冰暴过后，那座老谷仓的屋顶整个压塌了。你们换过的椽子断在雪泥里。','After the ice storm, the old barn\'s roof has come down completely. The rafters you replaced lie snapped in the slush.','Depois da tempestade de gelo, o telhado do celeiro velho veio todo abaixo. As vigas que trocaram estão partidas na lama de neve.'),
  t('韦德三天没来镇上，一个人在废墟里捡木头。他背对着你：“我说过要修的。我拖了二十年。”','Wade hasn\'t been to town in three days — just picking through the wreck alone. He keeps his back to you. "I said I\'d fix it. I put it off twenty years."','O Wade não aparece na vila há três dias — anda sozinho a apanhar os destroços. Fica de costas para ti. «Eu disse que o arranjava. Adiei vinte anos.»')],
 choices:[
  {t:t('什么也不说，和他一起捡木头','Say nothing. Pick up boards beside him','Não dizer nada. Apanhar tábuas ao lado dele'),fx:()=>{addTrust('wade',2);addLike('wade',1);stat('tex',2)},
   next:()=>say('',t('你们捡到天黑。他最后只说了一句：“明天还来吗？”你说来。他说：“好。”','You work until dark. Finally he says one thing: "Coming back tomorrow?" You say yes. He says, "Good."','Trabalham até escurecer. No fim ele diz só: «Voltas amanhã?» Dizes que sim. Ele diz: «Está bem.»'),t('信任 +2','Wade trust +2','Confiança do Wade +2'))},
  {t:t('拿出你画的那张修复图：“我们重盖一座。”','Bring out the plan you drew: "We build a new one."','Mostrar a planta que desenhaste: «Fazemos um novo.»'),req:()=>!!S.flags.rF_wadeBarn||NEED(t('先给谷仓画过图','Having drawn the barn plan','Ter desenhado a planta do celeiro')),fx:()=>{addTrust('wade',2);addLike('wade',2)},
   next:()=>say('',t('他接过图，看了很久，折好，放进胸口的口袋。“开春，”他说，“你画，我盖。”','He takes the plan, looks a long time, folds it and puts it in his chest pocket. "Spring," he says. "You draw. I build."','Pega na planta, olha muito tempo, dobra-a e guarda-a no bolso do peito. «Na primavera», diz. «Tu desenhas. Eu construo.»'),t('信任 +2 · 好感 +2','Wade trust +2 · affection +2','Confiança do Wade +2 · afeto +2'))},
  {t:t('劝他去厄尔那儿喝一杯，“谈谈就好了”','Tell him to come to Earl\'s for a drink — "talking helps"','Dizer-lhe para ir beber um copo ao Earl — «falar ajuda»'),fx:()=>addTrust('wade',-2),
   next:()=>say('',t('他回过头，像在看一个城里人：“你走吧。”回去的路上你才想明白，他要的不是谈谈。','He finally turns around, and looks at you like a city boy. "Go on home." You go. Halfway back you realize talking was never what he needed.','Finalmente vira-se, e olha para ti como para um menino da cidade. «Vai para casa.» Vais. A meio do caminho percebes que falar nunca foi o que ele precisava.'),t('信任 −2','Wade trust −2','Confiança do Wade −2'))}]})},

/* ---------- ASHLEY ---------- */
{id:'rF_ashley_date',when:()=>S.week>=6&&S.day===2&&S.slot===0&&rel('ashley').met&&rel('ashley').like>=4&&rel('ashley').trust>=3,run:()=>({
 title:t('清晨五点','Five a.m.','Cinco da manhã'),meta:DMETA('ashley'),
 text:[t('清晨五点，体育场的灯还没熄。阿什莉在跑道边等你，手里两杯黑咖啡，没有糖。“今天不练力量。跑步，然后吃早餐。你请。”','Five a.m., stadium lights still on. Ashley waits by the track with two black coffees, no sugar. "No lifting today. We run, then breakfast. Your treat."','Cinco da manhã, as luzes do estádio ainda acesas. A Ashley espera à beira da pista com dois cafés pretos, sem açúcar. «Hoje não há pesos. Corremos e depois pequeno-almoço. Pagas tu.»'),
  t('太阳从水塔后面升起来。她喘着气，第一次没看秒表。','The sun comes up behind the water tower. She\'s breathing hard, and for once doesn\'t check her stopwatch.','O sol nasce atrás da torre da água. Ela está ofegante e, pela primeira vez, não olha para o cronómetro.')],
 choices:[
  {t:t('跟她比最后一百米','Race her for the last hundred','Desafiá-la para os últimos cem metros'),req:()=>S.muscle>=3||NEED(t('肌肉 3 级','Muscle level 3','Músculo nível 3')),fx:()=>{addLike('ashley',2);addTrust('ashley',1);stat('tex',2)},
   next:()=>say('',t('你赢了半步。她不服，要求再跑一次。第二次她赢了，笑得像个十六岁的女孩。','You win by half a step. She demands a rematch. She wins the second, laughing like she\'s sixteen.','Ganhas por meio passo. Ela exige outra. Ganha a segunda, a rir como se tivesse dezasseis anos.'),t('好感 +2','Ashley affection +2','Afeto da Ashley +2'))},
  {t:t('坦白：你有时候讨厌被人盯着看','Admit it: sometimes you hate being stared at','Confessar: às vezes detestas que olhem para ti'),req:TRUTH('ashley'),fx:()=>{addTrust('ashley',3);addLike('ashley',1)},
   next:()=>say('',t('她沉默了很久，然后说：“我也是。所以我站在场边，不站在场上。”她把剩下的咖啡递给你。','She\'s quiet a long time. Then: "Me too. That\'s why I stand on the sideline, not the field." She hands you the rest of her coffee.','Fica muito tempo calada. Depois: «Eu também. É por isso que fico na linha lateral e não dentro do campo.» Passa-te o resto do café dela.'),t('信任 +3','Ashley trust +3','Confiança da Ashley +3'))},
  {t:`[${faceWord()}] `+t('跑完把湿透的上衣脱了','Peel off your soaked shirt after the run','Tirar a camisa encharcada no fim da corrida'),fx:()=>{addLike('ashley',0.5);addTrust('ashley',-1);flirt()},
   next:()=>say('',t('她看了一眼，翻了个白眼：“漂亮。现在穿上，凉了会抽筋。”','She looks, and rolls her eyes. "Pretty. Now put it back on before you cramp."','Olha e revira os olhos. «Muito bonito. Agora veste isso antes que te dê uma cãibra.»'),t('信任 −1','Ashley trust −1','Confiança da Ashley −1'))}]})},
{id:'rF_ashley_crisis',when:()=>S.week>21&&S.day===2&&S.slot===1&&rel('ashley').truth===true&&!!S.flags.ev_rF_ashley_date,run:()=>({
 title:t('广告牌','The billboard','O painel'),meta:CMETA('ashley'),
 text:[t('35 号州际公路匝道边立起一块新广告牌：铁马健身房，一个光着上身的男人，配字“德州制造”。那个男人是你。','A new billboard goes up by the I-35 ramp: Iron Mustang Gym, a shirtless man, the words "Made in Texas." The man is you.','Aparece um painel novo junto ao acesso da I-35: Ginásio Iron Mustang, um homem de tronco nu, as palavras «Feito no Texas». O homem és tu.'),
  t('上个月特拉维斯要拍“会员照”，送了你一年会员，你没细问。阿什莉在门口堵住你：“你说过你不是为了被看见才练的。”','Last month Travis wanted "member photos" and gave you a free year; you didn\'t ask questions. Ashley blocks the gym door. "You told me you didn\'t train to be looked at."','No mês passado o Travis quis «fotos de sócio» e deu-te um ano grátis; não fizeste perguntas. A Ashley barra-te a porta. «Disseste-me que não treinavas para olharem para ti.»')],
 choices:[
  {t:t('说实话：你贪了那张免费卡，你错了','Tell the truth: you wanted the free pass, and you were wrong','Dizer a verdade: quiseste o cartão grátis e erraste'),fx:()=>{addTrust('ashley',2)},
   next:()=>say('',t('她盯着你看了很久：“好。至少你没说‘只是一张照片’。”第二天，她陪你去找特拉维斯，让他把照片撤了。','She stares at you a long time. "Okay. At least you didn\'t say it\'s just a picture." Next day she goes with you to make Travis take it down.','Olha para ti muito tempo. «Está bem. Ao menos não disseste que é só uma fotografia.» No dia seguinte vai contigo obrigar o Travis a tirá-la.'),t('信任 +2','Ashley trust +2','Confiança da Ashley +2'))},
  {t:t('花 $300 解约，让特拉维斯撤掉广告牌','Pay $300 to break the deal and get the billboard pulled','Pagar $300 para rescindir e mandar tirar o painel'),req:MONEY(300),fx:()=>{S.cash-=300;addTrust('ashley',2);addLike('travis',-1)},
   next:()=>say('',t('特拉维斯耸耸肩：“随你。反正已经有三个女人打电话来问你是谁了。”阿什莉第一次笑出了声。','Travis shrugs. "Your call. Three women already phoned asking who you are." Ashley, beside you, laughs out loud for the first time.','O Travis encolhe os ombros. «Tu é que sabes. Já ligaram três mulheres a perguntar quem és.» A Ashley, ao teu lado, ri-se alto pela primeira vez.'),t('$−300 · 阿什莉信任 +2','$−300 · Ashley trust +2','$−300 · Confiança da Ashley +2'))},
  {t:t('“只是一张照片。身体又不会撒谎。”','"It\'s just a picture. Bodies don\'t lie."','«É só uma fotografia. O corpo não mente.»'),fx:()=>{addTrust('ashley',-2);flirt()},
   next:()=>say('',t('你用她的话回她。她把后半句补上：“——人会。”然后转身进了健身房。','You throw her own words back at her. She finishes the line: "— people do." Then she turns and walks into the gym.','Devolves-lhe as palavras dela. Ela termina a frase: «— as pessoas mentem.» Depois vira-se e entra no ginásio.'),t('信任 −2','Ashley trust −2','Confiança da Ashley −2'))}]})},

/* ---------- INÊS ---------- */
{id:'rF_ines_date',when:()=>S.week>=26&&S.day===3&&S.slot===2&&rel('ines').met&&rel('ines').like>=4&&rel('ines').trust>=3,run:()=>({
 title:t('小厨房','The little kitchen','A cozinha pequena'),meta:DMETA('ines'),
 text:[t('打烊后，伊内丝占了你的厨房，从行李箱里拿出羽衣甘蓝种子、里斯本香肠和一张阿玛利亚的旧唱片。','After closing, Inês takes over your kitchen and unpacks kale seeds, Lisbon sausage and an old Amália record.','Depois de fechar, a Inês apodera-se da tua cozinha e tira da mala sementes de couve, chouriço de Lisboa e um disco antigo da Amália.'),
  t('“唱片是我自己带的，别的是你妈让带的。”窗外是德州的大风，屋里是阿尔法马的味道。','"The record\'s mine. The rest your mother sent." Outside, Texas wind. Inside, the smell of Alfama.','«O disco é meu. O resto foi a tua mãe que mandou.» Lá fora, vento do Texas. Cá dentro, o cheiro de Alfama.')],
 choices:[
  {t:t('放唱片，在小厨房里跟她跳一支慢舞','Put the record on and slow-dance with her in the kitchen','Pôr o disco e dançar com ela devagar na cozinha'),fx:()=>{addLike('ines',2);stat('saud',4)},
   next:()=>say('',t('她踩了你两次脚，说是你的错，靴子太大。唱到第三首，她不说话了。','She steps on your feet twice and says it\'s your fault — the boots are too big. By the third song she\'s stopped talking.','Pisa-te duas vezes e diz que a culpa é tua — as botas são grandes demais. À terceira canção já não diz nada.'),t('好感 +2 · 乡愁 +4','Inês affection +2 · Homesickness +4','Afeto da Inês +2 · Saudade +4'))},
  {t:t('和她一起数阿尔法马石阶上的每一家店','Count off every shop on the Alfama steps together','Contar com ela todas as lojas das escadinhas de Alfama'),req:()=>S.stats.saud>=50||NEED(t('乡愁 50','Homesickness 50','Saudade 50')),fx:()=>{addTrust('ines',2);addLike('ines',1);stat('saud',6)},
   next:()=>say('',t('你们从大教堂数到观景台。数到那家被改成民宿的咖啡馆时，两个人同时停了下来。','You count from the cathedral up to the lookout. At the café that became a guesthouse, you both stop at once.','Contam da Sé até ao miradouro. No café que virou alojamento local, param os dois ao mesmo tempo.'),t('信任 +2 · 乡愁 +6','Inês trust +2 · Homesickness +6','Confiança da Inês +2 · Saudade +6'))},
  {t:t('告诉她你为什么走——不只是因为遗嘱','Tell her why you left — not just because of the will','Dizer-lhe porque partiste — não foi só pelo testamento'),req:TRUTH('ines'),fx:()=>{addTrust('ines',3)},
   next:()=>say('',t('她把汤勺放下：“你早该这么说。”但她没有走。她把你的碗又盛满了。','She puts down the ladle. "You should have said that a long time ago." But she doesn\'t leave. She fills your bowl again.','Pousa a concha. «Devias ter dito isso há muito tempo.» Mas não se vai embora. Volta a encher-te a tigela.'),t('信任 +3','Inês trust +3','Confiança da Inês +3'))},
  {t:t('跟她讲圣鲁伊斯的好','Tell her what\'s good about San Luís','Falar-lhe do que San Luís tem de bom'),req:()=>S.stats.tex>=40||NEED(t('德州味 40','Texanness 40','Texanidade 40')),fx:()=>{addLike('ines',-1);addTrust('ines',1);stat('tex',2)},
   next:()=>say('',t('她听着，笑了一下，有点难过：“你说‘我们镇’。你自己都没发现。”','She listens and smiles, a little sad. "You said \'our town.\' You didn\'t even notice."','Ouve e sorri, um pouco triste. «Disseste "a nossa terra". Nem reparaste.»'))}]})},
{id:'rF_ines_crisis',when:()=>S.week>20&&S.week>=31&&S.day===6&&S.slot===2&&rel('ines').truth===true&&!!S.flags.ev_rF_ines_date,run:()=>({
 title:t('出发层','Departures','Partidas'),meta:CMETA('ines'),
 text:[t('伊内丝的机票这次改不了了。鲁伊打电话给她，不是给你：你妈住院了。','This time Inês can\'t change her ticket. Rui called her — not you. Your mother\'s in the hospital.','Desta vez a Inês não consegue mudar o bilhete. O Rui ligou-lhe a ela — não a ti. A tua mãe está no hospital.'),
  t('她在店门口把行李箱立起来：“跟我回去。一个星期就好。你妈问了你三遍。”格蕾丝讲过：离开一周，一切归市政慈善基金。伊内丝知道。她还是问了。','She stands her suitcase up at the door. "Come back with me. Just one week. Your mother asked for you three times." Grace was clear: leave for a week and it all goes to the town charity. Inês knows. She asks anyway.','Põe a mala de pé à porta. «Vem comigo. Só uma semana. A tua mãe perguntou por ti três vezes.» A Grace foi clara: uma semana fora e tudo vai para a fundação municipal. A Inês sabe. Pergunta na mesma.')],
 choices:[
  {t:t('说实话，求她替你去陪妈妈','Tell the truth, and ask her to sit with your mother for you','Dizer a verdade e pedir-lhe que fique com a tua mãe por ti'),fx:()=>{addTrust('ines',2);stat('saud',3)},
   next:()=>say('',t('她哭了，然后点头：“我替你去。但你每天晚上要打视频，打到她睡着。”她走的时候，没让你送。','She cries, then nods. "I\'ll go for you. But you video-call every night until she falls asleep." When she leaves, she won\'t let you see her off.','Chora e depois acena. «Vou eu por ti. Mas fazes videochamada todas as noites até ela adormecer.» Quando parte, não te deixa ir com ela.'),t('信任 +2','Inês trust +2','Confiança da Inês +2'))},
  {t:t('开车送她去机场','Drive her to the airport','Levá-la de carro ao aeroporto'),req:()=>S.course.drive>=2||NEED(t('开车课 2','Driving lessons 2','Aulas de condução 2')),fx:()=>{addTrust('ines',2);addLike('ines',2);stat('saud',5)},
   next:()=>say('',t('这一次，站在外面的是你。她过了安检，回头，隔着玻璃用口型骂了一句里斯本的粗话。你笑了，眼睛是湿的。','This time you\'re the one left standing outside. Past security she turns and mouths a Lisbon curse at you through the glass. You laugh, eyes wet.','Desta vez és tu que ficas cá fora. Depois do controlo ela vira-se e, através do vidro, articula um palavrão bem lisboeta. Ris-te, de olhos molhados.'),t('信任 +2 · 好感 +2','Inês trust +2 · affection +2','Confiança da Inês +2 · afeto +2'))},
  {t:t('答应“下个月就回去”','Promise you\'ll be home "next month"','Prometer que voltas «no mês que vem»'),fx:()=>{addTrust('ines',-2);addLike('ines',1);S.flags.rF_inesPromise=true},
   next:()=>say('',t('她看了你很久：“你又这样。”她拖着箱子上了去奥斯汀的灰狗巴士，没有回头。','She looks at you a long time. "You\'re doing it again." She drags her case onto the Greyhound to Austin and doesn\'t look back.','Olha para ti muito tempo. «Estás outra vez a fazer isto.» Arrasta a mala para o autocarro da Greyhound para Austin e não olha para trás.'),t('信任 −2','Inês trust −2','Confiança da Inês −2'))}]})},

/* ---------- ROZ ---------- */
{id:'rF_roz_date',when:()=>S.week>=10&&S.day===4&&S.slot===2&&rel('roz').met&&rel('roz').like>=4&&rel('roz').trust>=3,run:()=>({
 title:t('钻塔上的夜','Night on the rig','Noite na sonda'),meta:DMETA('roz'),
 text:[t('罗兹开着公司的皮卡，把你带到镇外一座停工的钻塔下。“严格来说，我们俩都不该在这儿。”她递给你一顶安全帽。','Roz drives you out in the company truck to an idle rig outside town. "Technically, neither of us should be here." She hands you a hard hat.','A Roz leva-te na carrinha da empresa até uma sonda parada fora da vila. «Tecnicamente, nenhum de nós devia estar aqui.» Dá-te um capacete.'),
  t('从平台上看，圣鲁伊斯缩成一小片橘色的灯，远处是罐头厂黑黢黢的轮廓。','From the platform, San Luís shrinks to a patch of orange lights. Further off, the black outline of the cannery.','Da plataforma, San Luís encolhe numa mancha de luzes cor de laranja. Mais longe, o vulto negro da fábrica de conservas.')],
 choices:[
  {t:t('问她：特拉维斯到底想拿那块地做什么','Ask her what Travis really wants that land for','Perguntar-lhe para que é que o Travis quer mesmo o terreno'),req:()=>rel('roz').trust>=5||NEED(t('罗兹信任 5','Roz\'s trust 5','Confiança da Roz 5')),fx:()=>{addTrust('roz',1);S.flags.rF_rozHint=true},
   next:()=>say('',t('她看着罐头厂的方向，很久才开口：“去查一下‘孤星砂业’是谁注册的。我什么都没说。”','She looks toward the cannery a long while before she speaks. "Go look up who registered Lone Star Sand. I didn\'t say anything."','Fica muito tempo a olhar para a fábrica antes de falar. «Vai ver quem registou a Lone Star Sand. Eu não disse nada.»'),t('信任 +1 · 线索','Roz trust +1 · a lead','Confiança da Roz +1 · uma pista'))},
  {t:t('什么也不问，就看星星','Don\'t ask anything. Just watch the stars','Não perguntar nada. Só ver as estrelas'),fx:()=>{addLike('roz',2);addTrust('roz',1)},
   next:()=>say('',t('她给你指猎户座，又指出哪一颗其实是卫星。“抱歉，职业病。”你说这已经很浪漫了。','She points out Orion, then which one\'s actually a satellite. "Sorry. Occupational hazard." You tell her this is plenty romantic.','Mostra-te Orionte, depois qual delas é afinal um satélite. «Desculpa. Defeito profissional.» Dizes-lhe que isto já é muito romântico.'),t('好感 +2','Roz affection +2','Afeto da Roz +2'))},
  {t:`[${faceWord()}] `+t('趁风大靠过去','Lean in while the wind picks up','Encostar-te quando o vento aperta'),req:CHARM_REQ(55),fx:()=>{addLike('roz',1);addTrust('roz',-1);flirt()},
   next:()=>say('',t('她没躲，也没靠过来：“你这招对多少人用过？别回答。我是工程师，讨厌误差。”','She doesn\'t pull away, doesn\'t lean in either. "How many people have you tried that on? Don\'t answer. I\'m an engineer. I hate margins of error."','Não se afasta, mas também não se aproxima. «Com quantas pessoas já usaste isso? Não respondas. Sou engenheira. Detesto margens de erro.»'),t('信任 −1','Roz trust −1','Confiança da Roz −1'))}]})},
{id:'rF_roz_crisis',when:()=>S.week>20&&S.week>=33&&S.day===2&&S.slot===2&&rel('roz').truth===true&&!!S.flags.ev_rF_roz_date,run:()=>({
 title:t('她的名字','Her name','O nome dela'),meta:CMETA('roz'),
 text:[t('罗兹深夜敲你的后门，工装都没换。“特拉维斯查了服务器。他知道有人在复制邮件。”','Roz knocks on your back door late at night, still in her coveralls. "Travis audited the server. He knows someone\'s been copying emails."','A Roz bate-te à porta das traseiras a meio da noite, ainda de fato-macaco. «O Travis mandou verificar o servidor. Sabe que alguém andou a copiar emails.»'),
  t('“你们要是揭发他，文件里有我的名字。我会被开除，这一行再也待不下去。”她第一次看起来像在害怕。','"If y\'all go public, my name\'s in those files. I get fired, and I\'m done in this industry." For the first time she looks scared.','«Se vocês o denunciarem, o meu nome está nesses ficheiros. Sou despedida e acabou-se este ramo para mim.» Pela primeira vez parece ter medo.')],
 choices:[
  {t:t('答应她：她的名字不会出现','Promise her name stays out of it','Prometer-lhe que o nome dela fica de fora'),fx:()=>{addTrust('roz',2);S.flags.rF_rozShield=true},
   next:()=>say('',t('“你保证不了。”她说。“我知道。”你说，“但我会先烧了自己的手，再交出你的名字。”她笑了一下，是一个累坏了的笑。','"You can\'t promise that," she says. "I know," you say. "But I\'d burn my own hand before I gave up your name." She smiles — a worn-out smile.','«Não podes prometer isso», diz ela. «Eu sei», dizes tu. «Mas queimava a mão antes de dar o teu nome.» Ela sorri — um sorriso de quem está exausta.'),t('信任 +2','Roz trust +2','Confiança da Roz +2'))},
  {t:t('告诉她店里永远有她的位置','Tell her there\'s always a spot for her at the shop','Dizer-lhe que há sempre lugar para ela no restaurante'),fx:()=>{addTrust('roz',2);addLike('roz',1)},
   next:()=>say('',t('“我是工程师，你要我烤沙丁鱼？”她说。然后她哭了。你这才知道她有多累。','"I\'m an engineer and you want me grilling sardines?" she says. Then she cries, and you finally see how tired she is.','«Sou engenheira e queres-me a assar sardinhas?», diz ela. Depois chora, e só então percebes o cansaço dela.'),t('信任 +2','Roz trust +2','Confiança da Roz +2'))},
  {t:t('劝她为了镇子出来作证','Tell her she ought to testify, for the town','Dizer-lhe que devia testemunhar, pela vila'),fx:()=>addTrust('roz',-2),
   next:()=>say('',t('你说的每个字都对。她站起来：“对的话谁都会说，特拉维斯也会说。”后门关上的时候，风把纱门拍了三下。','Every word you say is right. She stands. "Anybody can say the right thing. Travis says it too." When the back door shuts, the wind bangs the screen three times.','Tudo o que dizes está certo. Ela levanta-se. «Qualquer um diz a coisa certa. O Travis também diz.» Quando a porta se fecha, o vento bate três vezes a rede mosquiteira.'),t('信任 −2','Roz trust −2','Confiança da Roz −2'))}]})},

/* ---------- KYLE ---------- */
{id:'rF_kyle_date',when:()=>S.week>=10&&S.day===6&&S.slot===2&&rel('kyle').met&&rel('kyle').like>=4&&rel('kyle').trust>=3,run:()=>({
 title:t('老舞厅','The dance hall','O salão de baile'),meta:DMETA('kyle'),
 text:[t('凯尔带你去邻县一座百年木头舞厅，地板被三代人的靴子磨得发亮。','Kyle takes you to a hundred-year-old wooden dance hall in the next county, its floor polished by three generations of boots.','O Kyle leva-te a um salão de baile de madeira com cem anos, no condado vizinho, com o soalho polido por três gerações de botas.'),
  t('乐队唱到一半，他凑过来：“下一首是两步舞。你会吗？我也不太会。”','Halfway through the set he leans over. "Next one\'s a two-step. You know how? I kinda don\'t either."','A meio do concerto inclina-se para ti. «A próxima é um two-step. Sabes dançar? Eu também não muito.»')],
 choices:[
  {t:t('拉他下舞池','Pull him onto the floor','Puxá-lo para a pista'),req:()=>S.stats.tex>=40||NEED(t('德州味 40','Texanness 40','Texanidade 40')),fx:()=>{addLike('kyle',2);addTrust('kyle',1);stat('tex',3)},
   next:()=>say('',t('你们跳得一塌糊涂，撞上了一对老夫妇。老太太没生气，拍拍凯尔的胳膊：“孩子，跟着他，他踩得准。”','You\'re a mess out there and bump into an old couple. The lady isn\'t mad; she pats Kyle\'s arm. "Follow him, honey. He\'s got the beat."','Dançam pessimamente e chocam com um casal de velhotes. A senhora não se zanga; dá uma palmadinha no braço do Kyle. «Segue-o, querido. Ele tem o ritmo.»'),t('好感 +2 · 德州味 +3','Kyle affection +2 · Texanness +3','Afeto do Kyle +2 · Texanidade +3'))},
  {t:t('借乐队的吉他，上台弹一段葡萄牙吉他','Borrow the band\'s guitar and play a Portuguese-guitar piece','Pedir a guitarra à banda e tocar um tema de guitarra portuguesa'),req:CHARM_REQ(50),fx:()=>{addLike('kyle',2);S.rep+=2},
   next:()=>say('',t('半个舞厅的人停下来听。凯尔站在台下，第一次没跟着哼，只是看着你。','Half the hall stops to listen. Kyle stands below the stage and, for once, doesn\'t hum along. He just watches you.','Metade do salão para para ouvir. O Kyle, em baixo, pela primeira vez não cantarola. Fica só a olhar para ti.'),t('好感 +2 · 口碑 +2','Kyle affection +2 · Reputation +2','Afeto do Kyle +2 · Reputação +2'))},
  {t:t('在停车场的皮卡后斗上，跟他一起写歌词','Write lyrics with him on the tailgate in the parking lot','Escrever letras com ele na caixa da carrinha, no parque'),fx:()=>{addTrust('kyle',2);addLike('kyle',1)},
   next:()=>say('',t('你们写了一段英语、一段葡语。他想叫它《公路上的潮水》。你说这儿没有海。他说：“所以才要写。”','You write one verse in English, one in Portuguese. He wants to call it "High Tide on the Highway." You point out there\'s no sea here. "That\'s why you write it," he says.','Escrevem uma estrofe em inglês e outra em português. Ele quer chamar-lhe «Maré Cheia na Estrada». Lembras-lhe que aqui não há mar. «É por isso que se escreve», diz ele.'),t('信任 +2','Kyle trust +2','Confiança do Kyle +2'))}]})},
{id:'rF_kyle_crisis',when:()=>S.week>20&&S.week>=27&&S.day===4&&S.slot===0&&rel('kyle').truth===true&&!!S.flags.ev_rF_kyle_date,run:()=>({
 title:t('新歌','The new song','A canção nova'),meta:CMETA('kyle'),
 text:[t('天没亮，凯尔抱着吉他坐在店门口台阶上，一夜没睡的样子。','Before dawn, Kyle is sitting on the shop steps with his guitar, looking like he hasn\'t slept.','Ainda não amanheceu e o Kyle está sentado nos degraus do restaurante, de guitarra ao colo, com cara de quem não dormiu.'),
  t('“我写了首歌，关于你。歌词里是‘他’，不是‘她’。”他盯着自己沾满机油的靴子，“周六在厄尔那儿首演。这个镇子……我不知道。我想先问你。”','"I wrote a song. About you. It says \'he,\' not \'she.\'" He stares at his greasy boots. "I\'m debuting it at Earl\'s Saturday. This town… I don\'t know. I wanted to ask you first."','«Escrevi uma canção. Sobre ti. Diz "ele", não "ela".» Olha para as botas cheias de óleo. «Estreio-a no Earl no sábado. Esta terra… não sei. Quis perguntar-te primeiro.»')],
 choices:[
  {t:t('“先唱给我听。我站第一排。”','"Play it for me first. I\'ll be front row."','«Toca-ma primeiro. Eu fico na primeira fila.»'),fx:()=>{addTrust('kyle',2);addLike('kyle',2);S.flags.rF_kyleSong='front'},
   next:()=>say('',t('周六晚上，他唱了。厄尔的酒吧安静了三秒，然后有人吹了声口哨——是厄尔自己。','Saturday night he sings it. Earl\'s goes quiet for three seconds, then somebody whistles — Earl himself.','No sábado à noite, canta-a. O bar do Earl fica três segundos em silêncio, e depois alguém assobia — o próprio Earl.'),t('信任 +2 · 好感 +2','Kyle trust +2 · affection +2','Confiança do Kyle +2 · afeto +2'))},
  {t:t('把它改成二重唱','Make it a duet','Fazer dela um dueto'),req:()=>rel('kyle').trust>=6||NEED(t('凯尔信任 6','Kyle\'s trust 6','Confiança do Kyle 6')),fx:()=>{addTrust('kyle',2);addLike('kyle',1);stat('saud',2);S.rep+=2;S.flags.rF_kyleSong='duet'},
   next:()=>say('',t('周六晚上，你唱葡语，他唱英语，谁也没换代词。台下有人没鼓掌，但鼓掌的人更多。','Saturday night you sing in Portuguese, he sings in English, and nobody changes a pronoun. Some people don\'t clap. More people do.','No sábado à noite cantas em português, ele em inglês, e ninguém muda um pronome. Há quem não bata palmas. Há mais quem bata.'),t('信任 +2 · 口碑 +2','Kyle trust +2 · Reputation +2','Confiança do Kyle +2 · Reputação +2'))},
  {t:t('问他能不能先把“他”改成“她”','Ask if he could change "he" to "she" for now','Perguntar se ele pode mudar «ele» para «ela» por agora'),fx:()=>{addTrust('kyle',-2);S.flags.rF_kyleSong='changed'},
   next:()=>say('',t('他说“当然”，说得太快了。周六他唱了改过的版本，唱得很好，一眼也没看你。','He nods and says "sure," too fast. Saturday he sings the changed version. He sings it well, and never once looks at you.','Acena e diz «claro», depressa demais. No sábado canta a versão alterada. Canta bem, e nem uma vez olha para ti.'),t('信任 −2','Kyle trust −2','Confiança do Kyle −2'))}]})},

/* ---------- DELPHINE ---------- */
{id:'rF_delphine_date',when:()=>S.week>=10&&S.day===3&&S.slot===1&&rel('delphine').met&&rel('delphine').like>=4&&rel('delphine').trust>=3,run:()=>({
 title:t('奥斯汀试吃','Tasting Austin','Provar Austin'),meta:DMETA('delphine'),
 text:[t('德尔菲娜周三中午把你从店里拐走，开了一个小时车到奥斯汀东区。“今天你是我的评委。”','Wednesday at noon Delphine kidnaps you from the shop and drives an hour to East Austin. "Today you\'re my judge."','Na quarta ao meio-dia a Delphine rapta-te do restaurante e conduz uma hora até ao leste de Austin. «Hoje és tu o meu júri.»'),
  t('最后一站是一家“葡式融合”新店。菜单上写着“蛋挞”，端上来的是一块冻芝士蛋糕。','Last stop: a new "Portuguese fusion" place. The menu says "custard tart." What arrives is a frozen cheesecake.','Última paragem: um sítio novo de «fusão portuguesa». A ementa diz «pastel de nata». O que chega é uma tarte de queijo congelada.')],
 choices:[
  {t:t('说实话：这不是蛋挞','Be honest: that\'s no custard tart','Ser franco: aquilo não é um pastel de nata'),req:()=>S.stats.oficio>=40||NEED(t('手艺 40','Craft 40','Ofício 40')),fx:()=>{addLike('delphine',1);addTrust('delphine',2);stat('oficio',2);S.online+=3},
   next:()=>say('',t('她把你的话一字不改地发了出去。第二天，那家店把“蛋挞”从菜单上删了，你的店多了一百个关注。','She posts your words exactly as you said them. Next day the place drops "custard tart" from its menu, and your shop gains a hundred followers.','Publica as tuas palavras tal e qual. No dia seguinte o sítio tira o «pastel de nata» da ementa e o teu restaurante ganha cem seguidores.'),t('信任 +2 · 线上评分 +3','Delphine trust +2 · Online rating +3','Confiança da Delphine +2 · Avaliação online +3'))},
  {t:`[${faceWord()}] `+t('让她给你拍一组奥斯汀街头的照片','Let her shoot a set of you on the Austin streets','Deixá-la fotografar-te nas ruas de Austin'),req:CHARM_REQ(50),fx:()=>{addLike('delphine',2);S.online+=5;flirt()},
   next:()=>say('',t('照片很好看，点赞很多。评论里有人问“这是哪个模特”，没人问你的店在哪儿。','The photos are gorgeous. Lots of likes. Someone in the comments asks "who\'s the model?" Nobody asks where your shop is.','As fotografias ficam lindas. Muitos gostos. Nos comentários alguém pergunta «quem é o modelo?». Ninguém pergunta onde fica o teu restaurante.'),t('好感 +2 · 线上评分 +5','Affection +2 · Online rating +5','Afeto +2 · Avaliação online +5'))},
  {t:t('问她为什么总回圣鲁伊斯','Ask why she keeps coming back to San Luís','Perguntar-lhe porque continua a voltar a San Luís'),req:()=>rel('delphine').trust>=5||NEED(t('德尔菲娜信任 5','Delphine\'s trust 5','Confiança da Delphine 5')),fx:()=>{addTrust('delphine',2);addLike('delphine',1)},
   next:()=>say('',t('她沉默了一下：“因为你的店是这一年里唯一一个没想讨好我的地方。”','She\'s quiet for a moment. "Because yours is the only place all year that didn\'t try to please me."','Fica calada um instante. «Porque o teu é o único sítio, este ano inteiro, que não tentou agradar-me.»'),t('信任 +2','Delphine trust +2','Confiança da Delphine +2'))}]})},
{id:'rF_delphine_crisis',when:()=>S.week>20&&S.week>=22&&S.day===1&&S.slot===1&&rel('delphine').truth===true&&!!S.flags.ev_rF_delphine_date,run:()=>({
 title:t('封面故事','Cover story','Artigo de capa'),meta:CMETA('delphine'),
 text:[t('德尔菲娜冲进店里，脸上是压不住的兴奋：奥斯汀一家大杂志要做你的封面故事。','Delphine bursts into the shop, unable to hide her excitement: a big Austin magazine wants you for a cover story.','A Delphine entra de rompante, sem conseguir esconder a excitação: uma grande revista de Austin quer fazer de ti artigo de capa.'),
  t('草稿标题是《泽家烧烤：一个葡萄牙男人的德州梦》，招牌照片被修成了英文新店名。第三段写的是若泽没寄出的信——你只跟她一个人说过。','The draft\'s headline: "Zé\'s BBQ: One Portuguese Man\'s Texas Dream." The photo of the sign has been retouched with a new English name. Paragraph three is about José\'s unsent letters — something you told only her.','O título do rascunho: «Zé\'s BBQ: o sonho texano de um português». A fotografia da tabuleta foi retocada com um nome novo em inglês. O terceiro parágrafo fala das cartas por enviar do José — coisa que só contaste a ela.')],
 choices:[
  {t:t('平静地说：信不能写，招牌不能改','Calmly: no letters, no new sign','Com calma: as cartas não, a tabuleta não'),fx:()=>{addTrust('delphine',2);S.online+=5;S.flags.rF_delphineStory='edited'},
   next:()=>say('',t('她咬着嘴唇，把第三段整段删了。“我习惯把所有东西都变成故事，”她说，“包括你。对不起。”文章上线时，招牌还是原来的样子。','She bites her lip, listens, and deletes paragraph three entirely. "I\'m used to turning everything into a story," she says. "You included. I\'m sorry." When it runs, the sign is the way it\'s always been.','Morde o lábio, ouve e apaga o terceiro parágrafo inteiro. «Estou habituada a transformar tudo numa história», diz. «Incluindo tu. Desculpa.» Quando o artigo sai, a tabuleta está como sempre foi.'),t('信任 +2 · 线上评分 +5','Delphine trust +2 · Online rating +5','Confiança da Delphine +2 · Avaliação online +5'))},
  {t:t('当着客人的面冲她发火','Blow up at her in front of the customers','Explodir com ela à frente dos clientes'),fx:()=>{addTrust('delphine',-2);addLike('delphine',-1);S.rep-=1},
   next:()=>say('',t('客人都低下了头。她把草稿留在柜台上，走了。文章没有上线，她的博客停了一周。','Every customer stares at their plate. She leaves the draft on the counter and goes. The story never runs, and her blog goes quiet for a week.','Os clientes todos olham para o prato. Ela deixa o rascunho no balcão e vai-se. O artigo nunca sai e o blogue dela fica calado uma semana.'),t('信任 −2','Delphine trust −2','Confiança da Delphine −2'))},
  {t:t('让她照发——火了再说','Let it run as is — fame first, feelings later','Deixar sair assim — primeiro a fama, depois logo se vê'),fx:()=>{addTrust('delphine',-2);S.online+=12;S.rep+=3;stat('saud',-5);S.flags.rF_delphineStory='ran'},
   next:()=>say('',t('文章火了，队排到了停车场。周日夜里你一个人读第三段，若泽的字被印成了别人的故事。德尔菲娜发来：“满意吗？”你没回。','It goes viral; the line runs into the parking lot. Sunday night, alone, you read paragraph three: José\'s words printed as someone else\'s story. Delphine texts: "Happy?" You don\'t answer.','O artigo rebenta; a fila chega ao parque. No domingo à noite, sozinho, lês o terceiro parágrafo: as palavras do José impressas como história de outra pessoa. A Delphine manda: «Contente?» Não respondes.'),t('信任 −2 · 线上评分 +12 · 乡愁 −5','Delphine trust −2 · Online rating +12 · Homesickness −5','Confiança da Delphine −2 · Avaliação online +12 · Saudade −5'))}]})},

/* ---------- GRACE ---------- */
{id:'rF_grace_date',when:()=>S.week>=14&&S.day===7&&S.slot===2&&rel('grace').met&&rel('grace').like>=4&&rel('grace').trust>=3,run:()=>({
 title:t('管辖区之外','Out of jurisdiction','Fora da jurisdição'),meta:DMETA('grace'),
 text:[t('格蕾丝打来电话，像在安排听证会：“韦科有家通宵餐馆，不归我管辖。七点，我开车。”','Grace calls, sounding like she\'s scheduling a hearing. "All-night diner in Waco. Outside my jurisdiction. Seven. I\'ll drive."','A Grace liga, como quem marca uma audiência. «Há um restaurante aberto toda a noite em Waco. Fora da minha jurisdição. Às sete. Eu conduzo.»'),
  t('灯管嗡嗡响。她点了一份山核桃派，把文件夹留在了车里。这是你第一次看见她两手空空。','The fluorescent lights hum. She orders pecan pie and leaves her folder in the car. It\'s the first time you\'ve seen her empty-handed.','As lâmpadas fluorescentes zumbem. Ela pede tarte de noz-pecã e deixa a pasta no carro. É a primeira vez que a vês de mãos vazias.')],
 choices:[
  {t:t('问她为什么回圣鲁伊斯','Ask why she came back to San Luís','Perguntar-lhe porque voltou para San Luís'),fx:()=>{addTrust('grace',2);addLike('grace',1)},
   next:()=>say('',t('“因为这里的人吵完架，第二天还会一起去教堂。”她用叉子切着派，“达拉斯的人不吵架，直接起诉。”','"Because people here fight and still sit in the same pew next morning." She cuts her pie with the side of her fork. "In Dallas nobody fights. They just sue."','«Porque aqui as pessoas zangam-se e no dia seguinte vão juntas à missa.» Corta a tarte com o garfo. «Em Dallas ninguém se zanga. Processam-se.»'),t('信任 +2','Grace trust +2','Confiança da Grace +2'))},
  {t:t('用正式英语讲个遗嘱笑话','Tell a probate joke in formal English','Contar uma anedota sobre testamentos em inglês formal'),req:()=>charm()+formalPenalty()>=50||NEED(t('魅力（含口音修正）50','Charm (with accent modifier) 50','Charme (com ajuste de sotaque) 50')),fx:()=>{addLike('grace',2);stat('tex',1)},
   next:()=>say('',t('她笑得把咖啡洒在了桌上。“‘遗嘱认证’这个词你念对了。”她用纸巾擦着桌子，“是我教的。”','She laughs so hard she spills her coffee. "You said \'probate\' right." She mops the table with a napkin. "I taught you that."','Ri-se tanto que entorna o café. «Disseste "probate" bem.» Limpa a mesa com um guardanapo. «Fui eu que te ensinei.»'),t('好感 +2','Grace affection +2','Afeto da Grace +2'))},
  {t:t('告诉她你在若泽的信里读到了什么','Tell her what you\'ve read in José\'s letters','Contar-lhe o que leste nas cartas do José'),req:()=>S.letters>=3||NEED(t('若泽的信 3 封','3 of José\'s letters','3 cartas do José')),fx:()=>{addTrust('grace',3);stat('saud',3)},
   next:()=>say('',t('她沉默了很久：“他签字那天问我，遗嘱能不能附一封信。我说法律上没有意义。”她低下头，“我错了。”','She\'s silent a long time. "The day he signed, he asked if he could attach a letter to the will. I told him it had no legal meaning." She looks down. "I was wrong."','Fica muito tempo calada. «No dia em que assinou, perguntou-me se podia juntar uma carta ao testamento. Disse-lhe que não tinha valor jurídico.» Baixa os olhos. «Enganei-me.»'),t('信任 +3','Grace trust +3','Confiança da Grace +3'))}]})},
{id:'rF_grace_crisis',when:()=>S.week>20&&S.week>=38&&S.day===1&&S.slot===0&&rel('grace').truth===true&&!!S.flags.ev_rF_grace_date,run:()=>({
 title:t('利益冲突','Conflict of interest','Conflito de interesses'),meta:CMETA('grace'),
 text:[t('特拉维斯的律师寄来挂号信：投诉市政律师与继承人“存在不当私人关系”，要求重审遗嘱。','A certified letter from Travis\'s lawyer: a complaint that the town attorney has "an improper personal relationship" with the heir, demanding the estate be reviewed.','Uma carta registada do advogado do Travis: queixa de que a advogada municipal tem «uma relação pessoal imprópria» com o herdeiro, exigindo a revisão da herança.'),
  t('“我继续负责，他们就有理由推翻一切。”她一直在按圆珠笔，“我回避，接手的是一个跟博伊德家打了三十年高尔夫的人。”','"If I stay on, they\'ve got grounds to throw it all out." She won\'t stop clicking her pen. "If I recuse, it goes to a man who\'s golfed with the Boyds for thirty years."','«Se eu continuar, têm motivo para anular tudo.» Não para de carregar na esferográfica. «Se me declarar impedida, passa para um homem que joga golfe com os Boyd há trinta anos.»')],
 choices:[
  {t:t('请她回避，你来担风险','Ask her to recuse; you\'ll take the risk','Pedir-lhe que se declare impedida; o risco é teu'),fx:()=>{addTrust('grace',2);addLike('grace',1);S.flags.rF_graceRecuse=true},
   next:()=>say('',t('她把笔放下了：“这是我听过最不合法律逻辑、也最正确的话。”她递交了回避申请，然后请了这辈子第一次假，来店里帮你洗盘子。','She puts the pen down. "That\'s the least legally sound and most correct thing I\'ve ever heard." She files to recuse, then takes the first vacation of her life — to wash dishes at the shop.','Pousa a caneta. «É a coisa menos jurídica e mais certa que já ouvi.» Pede o impedimento e tira as primeiras férias da vida — para lavar pratos no restaurante.'),t('信任 +2','Grace trust +2','Confiança da Grace +2'))},
  {t:t('用正式英语帮她起草一份声明','Help her draft a statement in formal English','Ajudá-la a redigir uma declaração em inglês formal'),req:()=>charm()+formalPenalty()>=55||NEED(t('魅力（含口音修正）55','Charm (with accent modifier) 55','Charme (com ajuste de sotaque) 55')),fx:()=>{addTrust('grace',2);addLike('grace',1);stat('tex',2)},
   next:()=>say('',t('你写了三遍，她改了两遍。委员会驳回了投诉。她把草稿留下，说要裱起来——“你第一份没有拼写错误的文件”。','You write it three times; she edits it twice. The board dismisses the complaint. She keeps your draft to frame — "your first document without a spelling mistake."','Escreves três vezes; ela corrige duas. A comissão arquiva a queixa. Ela guarda o rascunho para emoldurar — «o teu primeiro documento sem erros de ortografia».'),t('信任 +2 · 德州味 +2','Grace trust +2 · Texanness +2','Confiança da Grace +2 · Texanidade +2'))},
  {t:t('让她别管程序，先把这事压下去','Tell her to forget procedure and just bury it','Dizer-lhe para esquecer o procedimento e abafar o assunto'),fx:()=>addTrust('grace',-2),
   next:()=>say('',t('“你知道你在请一个律师做什么吗？”她的声音冷下来，“你在请我变成特拉维斯。”她把挂号信收进抽屉。那一晚的夜跑，她一个人去了。','"Do you know what you\'re asking a lawyer to do?" Her voice goes cold. "You\'re asking me to be Travis." She puts the letter in a drawer. That night she runs alone.','«Sabes o que estás a pedir a uma advogada?» A voz arrefece. «Estás a pedir-me que seja o Travis.» Guarda a carta numa gaveta. Nessa noite vai correr sozinha.'),t('信任 −2','Grace trust −2','Confiança da Grace −2'))}]})},

/* ---------- MAYA ---------- */
{id:'rF_maya_date',when:()=>S.week>=9&&S.day===5&&S.slot===2&&rel('maya').met&&rel('maya').like>=4&&rel('maya').trust>=3,run:()=>({
 title:t('国会大道','South Congress','South Congress'),meta:DMETA('maya'),
 text:[t('玛雅周五一下课，就把你塞进她那辆空调坏掉的旧车：“今晚去奥斯汀。我让你看看什么叫正常的地方。”','The minute Friday class ends, Maya stuffs you into her old car with the broken AC. "Austin tonight. I\'m gonna show you what a normal place looks like."','Mal acaba a aula de sexta, a Maya enfia-te no carro velho dela, com o ar condicionado avariado. «Hoje vamos a Austin. Vou mostrar-te o que é um sítio normal.»'),
  t('她点了一杯八块钱的手冲咖啡，喝了一口，闭上眼：“这才叫活着。”','She orders an eight-dollar pour-over, sips, and closes her eyes. "Now this is living."','Pede um café de filtro de oito dólares, dá um gole e fecha os olhos. «Isto é que é viver.»')],
 choices:[
  {t:t('说你也喜欢这儿，像里斯本的夜晚','Say you love it too — it feels like a Lisbon night','Dizer que também gostas — parece uma noite de Lisboa'),req:()=>S.stats.saud>=40||NEED(t('乡愁 40','Homesickness 40','Saudade 40')),fx:()=>{addLike('maya',2);stat('saud',2);S.flags.rF_mayaAustin=(S.flags.rF_mayaAustin||0)+1},
   next:()=>say('',t('她抓住你的胳膊：“我就知道！”那一晚她讲了一个小时的未来，没有一句里有圣鲁伊斯。','She grabs your arm. "I knew it!" That night she talks about the future for an hour, and San Luís isn\'t in a single sentence.','Agarra-te o braço. «Eu sabia!» Nessa noite fala uma hora do futuro e San Luís não aparece numa única frase.'),t('好感 +2','Maya affection +2','Afeto da Maya +2'))},
  {t:t('说咖啡不错，但你有点想圣鲁伊斯的安静','Say the coffee\'s good, but you kind of miss the quiet of San Luís','Dizer que o café é bom, mas que tens saudades do sossego de San Luís'),req:()=>S.stats.tex>=30||NEED(t('德州味 30','Texanness 30','Texanidade 30')),fx:()=>{addTrust('maya',2);addLike('maya',-0.5);stat('tex',2)},
   next:()=>say('',t('她愣了一下，笑了，有点受伤：“你被同化了。”回去的路上，她把车窗摇下来，让平原的风灌进来。她一句话也没说，但也没生气。','She blinks, then laughs, a little hurt. "You\'ve gone native." On the drive back she rolls the window down and lets the prairie wind pour in. She doesn\'t say a word, but she isn\'t mad.','Fica surpreendida e ri-se, um pouco magoada. «Foste assimilado.» No regresso abre a janela e deixa entrar o vento da pradaria. Não diz nada, mas não está zangada.'),t('信任 +2','Maya trust +2','Confiança da Maya +2'))},
  {t:t('问她：是想去奥斯汀，还是不想留在任何地方','Ask: is it Austin she wants, or just never staying?','Perguntar: é Austin que ela quer, ou só nunca ficar?'),req:TRUTH('maya'),fx:()=>{addTrust('maya',3);addLike('maya',1)},
   next:()=>say('',t('她停在一家关了门的书店橱窗前，看了很久自己的倒影。“我从十八岁开始，每个地方都只租一年。”她说，“你是第一个问我为什么的人。”','She stops at the window of a closed bookstore and looks at her reflection a long time. "Since I was eighteen I\'ve never leased anywhere for more than a year," she says. "You\'re the first person who\'s asked why."','Para à frente da montra de uma livraria fechada e olha muito tempo para o reflexo. «Desde os dezoito anos que nunca arrendei nada por mais de um ano», diz. «És a primeira pessoa que me pergunta porquê.»'),t('信任 +3','Maya trust +3','Confiança da Maya +3'))}]})},
{id:'rF_maya_crisis',when:()=>S.week>20&&S.week>=34&&S.day===5&&S.slot===1&&rel('maya').truth===true&&!!S.flags.ev_rF_maya_date,run:()=>({
 title:t('聘书','The offer','A proposta'),meta:CMETA('maya'),
 text:[t('玛雅拿到了奥斯汀一所大学的聘书。她把信拍在柜台上：“一个小时车程。你满了 48 周就过来，店交给玛丽索尔。”她连你的房租都算好了。','Maya has an offer from a university in Austin. She slaps the letter on your counter. "One hour\'s drive. Finish your 48 weeks and come — Marisol can run the shop." She\'s even worked out your rent.','A Maya recebeu uma proposta de uma universidade em Austin. Bate com a carta no balcão. «Uma hora de carro. Acabas as 48 semanas e vens — a Marisol fica com o restaurante.» Até a tua renda já calculou.'),
  t('然后她看见墙上贴着的圣安东尼节筹备表，你的名字写在最上面。她的笑停住了：“你是不是根本没打算走？”','Then she sees the Santo António festival sign-up sheet on the wall, your name at the top. Her smile stops. "You were never planning to leave, were you?"','Depois vê na parede a folha da organização da festa de Santo António, com o teu nome no topo. O sorriso para. «Nunca pensaste ir embora, pois não?»')],
 choices:[
  {t:t('说实话：你还不知道，但不想因为怕停下来而走','Tell the truth: you don\'t know yet — but you won\'t leave just because you\'re scared of stopping','Dizer a verdade: ainda não sabes — mas não vais partir só por medo de parar'),fx:()=>{addTrust('maya',2)},
   next:()=>say('',t('她把聘书折了又展开：“你这是在说我。”她没生气，只是问圣安东尼节需不需要一个会做表格的人。','She folds the letter and unfolds it. "You\'re talking about me." She isn\'t angry. She just asks if the festival could use somebody good with spreadsheets.','Dobra a carta e volta a desdobrá-la. «Estás a falar de mim.» Não está zangada. Só pergunta se a festa precisa de alguém que saiba fazer folhas de cálculo.'),t('信任 +2','Maya trust +2','Confiança da Maya +2'))},
  {t:t('开车送她去奥斯汀看房，路上说清楚','Drive her to Austin to see apartments and talk it through','Levá-la a Austin ver casas e falar de tudo pelo caminho'),req:()=>S.course.drive>=1||NEED(t('开车课 1','Driving lessons 1','Aulas de condução 1')),fx:()=>{addTrust('maya',2);addLike('maya',1)},
   next:()=>say('',t('一路上你们说了她想要的、你想要的，和中间那一个小时。回来时她说：“一个小时，其实不远。”','On the road you talk about what she wants, what you want, and the hour in between. On the way back she says, "An hour isn\'t really that far."','Pelo caminho falam do que ela quer, do que tu queres e da hora que fica no meio. No regresso ela diz: «Uma hora afinal não é assim tão longe.»'),t('信任 +2','Maya trust +2','Confiança da Maya +2'))},
  {t:t('说你会跟她去奥斯汀','Say you\'ll come to Austin','Dizer que vais com ela para Austin'),fx:()=>{addTrust('maya',-2);addLike('maya',1);S.flags.rF_mayaAustin=(S.flags.rF_mayaAustin||0)+1},
   next:()=>say('',t('她高兴了一整周，不停地发奥斯汀的公寓链接给你。你每条都回“好看”，一条也没点开。','She\'s happy all week, sending you link after link to Austin apartments. You reply "nice" to every one and open none of them.','Fica contente a semana inteira, a mandar-te links de apartamentos em Austin. Respondes «giro» a todos e não abres nenhum.'),t('信任 −2','Maya trust −2','Confiança da Maya −2'))}]})}
);
})();
